public Instruction copy() {
        Instruction i = null;
        // "Constant" instruction, no need to duplicate
        if (InstructionConst.getInstruction(this.getOpcode()) != null) {
            i = this;
        } else {
            try {
                i = (Instruction) clone();
            } catch (final CloneNotSupportedException e) {
                System.err.println(e);
            }
        }
        return i;
    }

public static Instruction readInstruction( final ByteSequence bytes ) throws IOException {
        boolean wide = false;
        short opcode = (short) bytes.readUnsignedByte();
        Instruction obj = null;
        if (opcode == Const.WIDE) { // Read next opcode after wide byte
            wide = true;
            opcode = (short) bytes.readUnsignedByte();
        }
        final Instruction instruction = InstructionConst.getInstruction(opcode);
        if (instruction != null) {
            return instruction; // Used predefined immutable object, if available
        }

        switch (opcode) {
            case Const.BIPUSH:
                obj = new BIPUSH();
                break;
            case Const.SIPUSH:
                obj = new SIPUSH();
                break;
            case Const.LDC:
                obj = new LDC();
                break;
            case Const.LDC_W:
                obj = new LDC_W();
                break;
            case Const.LDC2_W:
                obj = new LDC2_W();
                break;
            case Const.ILOAD:
                obj = new ILOAD();
                break;
            case Const.LLOAD:
                obj = new LLOAD();
                break;
            case Const.FLOAD:
                obj = new FLOAD();
                break;
            case Const.DLOAD:
                obj = new DLOAD();
                break;
            case Const.ALOAD:
                obj = new ALOAD();
                break;
