                break;
            case Const.MULTIANEWARRAY:
                obj = new MULTIANEWARRAY();
                break;
            case Const.IFNULL:
                obj = new IFNULL();
                break;
            case Const.IFNONNULL:
                obj = new IFNONNULL();
                break;
            case Const.GOTO_W:
                obj = new GOTO_W();
                break;
            case Const.JSR_W:
                obj = new JSR_W();
                break;
            case Const.BREAKPOINT:
                obj = new BREAKPOINT();
                break;
            case Const.IMPDEP1:
                obj = new IMPDEP1();
                break;
            case Const.IMPDEP2:
                obj = new IMPDEP2();
                break;
            default:
                throw new ClassGenException("Illegal opcode detected: " + opcode);

        }

        if (wide
                && !((obj instanceof LocalVariableInstruction) || (obj instanceof IINC) || (obj instanceof RET))) {
            throw new ClassGenException("Illegal opcode after wide: " + opcode);
        }
        obj.setOpcode(opcode);
        obj.initFromFile(bytes, wide); // Do further initializations, if any
        return obj;
    }

