public void addObserver( final ClassObserver o ) {
        if (observers == null) {
            observers = new ArrayList<>();
        }
        observers.add(o);
    }

public void removeObserver( final ClassObserver o ) {
        if (observers != null) {
            observers.remove(o);
        }
